The first issue with your code is that the first character of the score property is always a " which means it's always invalid JSON.

To solve this you can convert the score to a string first and then wrap it in quotation marks so the JSON is written:

var answer_id = answer.id.split('.')[0]
var answer = await answer_id + '.json'

answer = (function(json) {
    json.score = '{"'+json.score+'"}'
    return json
})(await answer + '/score').catch(err => {
    if (err.message == 'The network request was interrupted.') {
        return json
    }
    throw err
})

